// AddverListMappings The mapping of your CSV column names to PostGrid address fields. Each value is
// the name of a column in your uploaded file.
type AddverListMappings struct {
	// City The column containing the city of each address.
	City *string `json:"city,omitempty"`

	// Country The column containing the 2-letter ISO country code of each address (e.g.
	// `US`, not `United States`).
	Country *string `json:"country,omitempty"`

	// FirstName The column containing the first name of the person at each address. Only
	// used when NCOA is run.
	FirstName *string `json:"firstName,omitempty"`

	// FullName The column containing the full name of the person at each address. Can
	// be supplied instead of `firstName` and `lastName`. Only used when NCOA
	// or CCOA is run.
	FullName *string `json:"fullName,omitempty"`

	// LastName The column containing the last name of the person at each address. Only
	// used when NCOA is run.
	LastName *string `json:"lastName,omitempty"`

	// Line1 The column containing the first line of each address. If your entire
	// address is in a single column, specify only this mapping.
	Line1 string `json:"line1"`

	// Line2 The column containing the second line of each address.
	Line2 *string `json:"line2,omitempty"`

	// PostalOrZip The column containing the postal or ZIP code of each address.
	PostalOrZip *string `json:"postalOrZip,omitempty"`

	// ProvinceOrState The column containing the province or state of each address.
	ProvinceOrState *string `json:"provinceOrState,omitempty"`
}

// AddverListUploadMultiPart The fields used to upload a new bulk verification list.
type AddverListUploadMultiPart struct {
	// DefaultCountry An ISO 2-letter country code used as the fallback when a row is missing a
	// value in the `country` column.
	DefaultCountry *string            `json:"defaultCountry,omitempty"`
	File           openapi_types.File `json:"file"`

	// Mappings The mapping of your CSV column names to PostGrid address fields.
	Mappings AddverListMappings `json:"mappings"`

	// Name A name for the uploaded list. This only affects what is displayed in the
	// dashboard.
	Name string `json:"name"`

	// RunCCOA Whether to run CCOA (Canada Post change of address) on the list. Note
	// that a list cannot run both NCOA and CCOA — split mixed US/Canadian
	// files into separate lists.
	RunCCOA *bool `json:"runCCOA,omitempty"`

	// RunNCOA Whether to run NCOA (US National Change of Address) on the list.
	RunNCOA *bool `json:"runNCOA,omitempty"`

	// UseGeocode Whether to append geographical location information (latitude, longitude)
	// to your output. Bulk geocoding must be enabled by contacting support.
	UseGeocode *bool `json:"useGeocode,omitempty"`

	// UseIntlVerification Whether to perform international (outside US & Canada) verification.
	UseIntlVerification *bool `json:"useIntlVerification,omitempty"`

	// UseProperCase Whether to return addresses in Proper Case.
	UseProperCase *bool `json:"useProperCase,omitempty"`
}

